// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX3} from "../src/MultiplicatorX3.sol";

contract InvMutTest is Test {
    MultiplicatorX3 c;
    function setUp() public { c = new MultiplicatorX3(); }

    function testFuzz_property(uint256 amount, address adr) public {
        // Admissible domain: any positive amount to any recipient; contract starts unfunded.
        vm.assume(amount > 0);
        vm.assume(adr != address(0));

        // Fund the caller so the value transfer can be attempted.
        vm.deal(address(this), amount);

        // Drive c through multiplicate, observing success/reversion on the public surface.
        bool ok;
        try c.multiplicate{value: amount}(adr) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: with a positive msg.value against the (zero) pre-call balance,
        // the guard (msg.value >= balance, balance now including msg.value) is taken and
        // the reference's transfer of balance+msg.value (= 2*amount > amount held) MUST
        // revert. The mutant ('>' instead of '>=') skips the transfer when
        // msg.value == balance, so its call succeeds — breaking the rule.
        assertTrue(!ok, "multiplicate with msg.value equal to balance must revert (entire payout unpayable)");
    }
}
